{"type":"item.completed","item":{"id":"item_26","type":"command_execution","command":"/bin/zsh -lc "nl -ba src/lib.rs | sed -n '1,180p'"","aggregated_output":"     1	//! Partition a non-negative sequence into exactly `groups` contiguous blocks.
     2	//!
     3	//! Each DP layer is optimized with a monotone convex hull.  Prefix sums are
     4	//! non-decreasing, so both inserted slopes and query positions are monotone.
     5	
     6	use std::collections::VecDeque;
     7	
     8	#[derive(Clone, Copy)]
     9	struct Line {
    10	    slope: i128,
    11	    intercept: i128,
    12	}
    13	
    14	impl Line {
    15	    fn value_at(self, x: i128) -> i128 {
    16	        self.slope * x + self.intercept
    17	    }
    18	}
    19	
    20	/// Returns whether `middle` is never the minimum after `first` and before
    21	/// `last`.  Slopes must be strictly decreasing.
    22	fn is_redundant(first: Line, middle: Line, last: Line) -> bool {
    23	    // intersection(first, middle) >= intersection(middle, last)
    24	    (middle.intercept - first.intercept) * (middle.slope - last.slope)
    25	        >= (last.intercept - middle.intercept) * (first.slope - middle.slope)
    26	}
    27	
    28	fn add_line(hull: &mut VecDeque<Line>, candidate: Line) {
    29	    // Zeros can yield equal prefix sums and hence equal slopes.  Only the
    30	    // lowest intercept can ever be useful.
    31	    if let Some(last) = hull.back() {
    32	        if last.slope == candidate.slope {
    33	            if last.intercept <= candidate.intercept {
    34	                return;
    35	            }
    36	            hull.pop_back();
    37	        }
    38	    }
    39	    while hull.len() >= 2
    40	        && is_redundant(hull[hull.len() - 2], hull[hull.len() - 1], candidate)
    41	    {
    42	        hull.pop_back();
    43	    }
    44	    hull.push_back(candidate);
    45	}
    46	
    47	pub fn min_squared_partition_cost(values: &[u64], groups: usize) -> u128 {
    48	    assert!(!values.is_empty());
    49	    assert!((1..=values.len()).contains(&groups));
    50	
    51	    let n = values.len();
    52	    let mut prefix = vec![0_i128; n + 1];
    53	    for (index, &value) in values.iter().enumerate() {
    54	        prefix[index + 1] = prefix[index] + value as i128;
    55	    }
    56	
    57	    // dp[j] is the optimum for the first j values using the previous number
    58	    // of groups.  `i128` safely contains every product in the stated bounds.
    59	    let infinity = i128::MAX;
    60	    let mut previous = vec![infinity; n + 1];
    61	    previous[0] = 0;
    62	
    63	    for group in 1..=groups {
    64	        let mut current = vec![infinity; n + 1];
    65	        let mut hull = VecDeque::with_capacity(n - group + 1);
    66	        let line_for = |index: usize| {
    67	            let sum = prefix[index];
    68	            Line {
    69	                slope: -2 * sum,
    70	                intercept: previous[index] + sum * sum,
    71	            }
    72	        };
    73	
    74	        add_line(&mut hull, line_for(group - 1));
    75	        for end in group..=n {
    76	            let sum = prefix[end];
    77	            while hull.len() >= 2
    78	                && hull[0].value_at(sum) >= hull[1].value_at(sum)
    79	            {
