    81	            }
    82	            current[end] = sum * sum + hull[0].value_at(sum);
    83	
    84	            if end < n && previous[end] != infinity {
    85	                add_line(&mut hull, line_for(end));
    86	            }
    87	        }
    88	        previous = current;
    89	    }
    90	
    91	    previous[n] as u128
